//! Differential check of the number helpers against libc++ output.
//!
//! `rust/tools/diff/tochars.cpp` writes `<hex bits> <std::to_chars text>` lines; run with `TOKSPUR_DIFF_TO_CHARS=<file> cargo test -- --ignored`.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stderr)]

use tokspur_json::{from_chars_f64, to_chars_shortest};

#[test]
#[ignore = "needs a corpus generated by rust/tools/diff/tochars.cpp"]
fn to_chars_and_from_chars_match_libcxx_corpus() {
    let path = std::env::var("TOKSPUR_DIFF_TO_CHARS").expect("TOKSPUR_DIFF_TO_CHARS");
    let corpus = std::fs::read_to_string(path).unwrap();
    let mut compared = 0usize;
    for line in corpus.lines() {
        let (bits, text) = line.split_once(' ').unwrap();
        let value = f64::from_bits(u64::from_str_radix(bits, 16).unwrap());
        assert_eq!(
            to_chars_shortest(value).as_deref(),
            Some(text),
            "bits {bits}"
        );
        let parsed = from_chars_f64(text).unwrap();
        assert_eq!(parsed.to_bits(), value.to_bits(), "round trip {text}");
        compared += 1;
    }
    assert!(compared > 0);
    eprintln!("compared {compared} libc++ to_chars/from_chars values");
}
